"use client";

import { motion } from "motion/react";

export function BlurInTextTailwind({ text = "Motion that feels considered, not decorated." }) {
  const words = text.split(" ");
  return (
    <h2 aria-label={text} className="text-4xl font-semibold tracking-tight text-zinc-100">
      {words.map((w, i) => (
        <motion.span
          key={i}
          aria-hidden
          className="inline-block"
          initial={{ opacity: 0, filter: "blur(12px)", y: 8 }}
          animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
          transition={{ duration: 0.6, delay: i * 0.08, ease: "easeOut" }}
        >
          {w}
          {i < words.length - 1 && "\u00A0"}
        </motion.span>
      ))}
    </h2>
  );
}
